def checkPossibility(nums):
    a = list(nums)
    used = False
    for i in range(1, len(a)):
        if a[i - 1] > a[i]:
            if used:
                return False
            used = True
            if i >= 2 and a[i - 2] > a[i]:
                a[i] = a[i - 1]
            else:
                a[i - 1] = a[i]
    return True
